/// <summary>
/// The <c>METBulkFreeTextInvoiceWorkflowSubmissionMainUIBuilder</c> class is responsible for building <c>SysOperation</c> dialog UI for bulk free text invoice workflow submission.
/// </summary>
public class METBulkFreeTextInvoiceWorkflowSubmissionMainUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField     dialogFieldFileName;
    DialogField     numberOfThreads;

}

Method.Source:
/// <summary>
/// Overrides the defaults in order to handle events on dialogs.
/// </summary>
public void postRun()
{
    super();

    METBulkFreeTextInvoiceWorkflowSubmissionMainContract contract = this.dataContractObject() as METBulkFreeTextInvoiceWorkflowSubmissionMainContract;

    dialogFieldFileName = this.bindInfo().getDialogField(contract, methodStr(METBulkFreeTextInvoiceWorkflowSubmissionMainContract, parmDMFFileName));
    dialogFieldFileName.fieldControl().mandatory(true);

    dialogFieldFileName.registerOverrideMethod(
        methodStr(FormStringControl, Modified),
        methodStr(METBulkFreeTextInvoiceWorkflowSubmissionMainUIBuilder, fileNameModified),
        this);

    numberOfThreads = this.bindInfo().getDialogField(contract, methodStr(METBulkFreeTextInvoiceWorkflowSubmissionMainContract, parmNoOfThreads));
    numberOfThreads.value(SalesParameters::find().METBulkWorkflowNoOfThreads);
}

/// <summary>
/// Performs a modified method for DMF file name.
/// </summary>
/// <param name="_fileNameControl">
/// The DMF file name form string control.
/// </param>
/// <returns>
/// True when file name is valid, else false.
/// </returns>
public boolean fileNameModified(FormStringControl _fileNameControl)
{
    CustInvoiceTable    invoiceTable;
    Filename            fileName = _fileNameControl.text();
    boolean             ret      = true;

    select firstonly RecId from invoiceTable
        where invoiceTable.METDMFImportFileName == fileName;

    if (invoiceTable.RecId == 0)
    {
        ret = checkFailed("@MET:METFTIDMFFileNameValid");
    }

    return ret;
}
